-- Hold the checked parent state through the child transaction. A terminal
-- transition then either precedes this check or waits for the child to commit.
CREATE OR REPLACE FUNCTION consulting_reject_terminal_child_write()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE
    old_parent UUID;
    new_parent UUID;
    parent_status TEXT;
BEGIN
    IF TG_OP <> 'INSERT' THEN old_parent := OLD.engagement_id; END IF;
    IF TG_OP <> 'DELETE' THEN new_parent := NEW.engagement_id; END IF;
    -- Engagement IDs are globally unique. Acquire both parents in the same
    -- order if a child is reassigned, including for callers subject to RLS.
    FOR parent_status IN
        SELECT status FROM consulting_engagements
        WHERE id IN (old_parent, new_parent)
        ORDER BY id FOR SHARE
    LOOP
        IF parent_status IN ('SUSTAINED', 'CORRECTIVE') THEN
            RAISE EXCEPTION USING
                ERRCODE = 'P0001',
                MESSAGE = 'terminal consulting engagement is immutable',
                CONSTRAINT = 'consulting_terminal_immutable';
        END IF;
    END LOOP;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$$;
